    /// <summary>A decimal as it crosses the bridge: the four ints of decimal.GetBits.</summary>
    [StructLayout(LayoutKind.Sequential)]
    internal struct CcmDecimal
    {
        public int Lo;
        public int Mid;
        public int Hi;
        public int Flags;

        public static CcmDecimal From(decimal value)
        {
            int[] bits = decimal.GetBits(value);
            return new CcmDecimal { Lo = bits[0], Mid = bits[1], Hi = bits[2], Flags = bits[3] };
        }

        public decimal ToDecimal()
        {
            return new decimal(new[] { Lo, Mid, Hi, Flags });
        }
    }

