    /// <summary>One C# façade per native object while the façade lives, so an object that comes
    /// back from native code is the same C# object (reference equality, Assert.AreSame).</summary>
    internal static class CcmObjects
    {
        private static readonly Dictionary<ulong, WeakReference> Facades = new Dictionary<ulong, WeakReference>();
        private static int pruneAt = 64;

        public static void Register(ulong key, object facade)
        {
            lock (Facades)
            {
                Facades[key] = new WeakReference(facade);
                Prune();
            }
        }

        /// <summary>The façade of the object a handle holds: the existing one (the extra handle is
        /// released), else a new one; null for a null handle.</summary>
        public static T Wrap<T, THandle>(THandle handle, Func<THandle, T> create)
            where T : class
            where THandle : SafeHandle, ICcmHandle
        {
            if (handle == null || handle.IsInvalid)
            {
                return null;
            }
            ulong key = handle.Key;
            lock (Facades)
            {
                WeakReference existing;
                if (Facades.TryGetValue(key, out existing))
                {
                    var facade = existing.Target as T;
                    if (facade != null)
                    {
                        handle.Dispose();
                        return facade;
                    }
                }
                T created = create(handle);
                Facades[key] = new WeakReference(created);
                Prune();
                return created;
            }
        }

        private static void Prune()
        {
            if (Facades.Count < pruneAt)
            {
                return;
            }
            var dead = new List<ulong>();
            foreach (KeyValuePair<ulong, WeakReference> entry in Facades)
            {
                if (!entry.Value.IsAlive)
                {
                    dead.Add(entry.Key);
                }
            }
            foreach (ulong key in dead)
            {
                Facades.Remove(key);
            }
            pruneAt = Math.Max(64, Facades.Count * 2);
        }
    }
